    /// Adds an injected `file:` workspace package (identified by its full
    /// package key, e.g. `@repo/shared@file:packages/shared`) to the pruned
    /// `packages` and `snapshots` maps, traversing its transitive dependencies
    /// and adding those as well.
    fn collect_injected_package(
        &self,
        package_key: &str,
        pruned_packages: &mut Packages,
        pruned_snapshots: &mut Option<Snapshots>,
    ) -> Result<(), crate::Error> {
        let mut stack = vec![package_key.to_string()];
        while let Some(key) = stack.pop() {
            // Skip keys we've already collected to avoid redundant work and
            // cycles.
            if pruned_snapshots
                .as_ref()
                .is_some_and(|snapshots| snapshots.contains_key(&key))
            {
