            // The `packages` entry is keyed without any peer suffix, so strip it
            // off before looking the package up.
            let dp = DepPath::parse(self.version(), key.as_str())?;
            let base_key = self.format_key(dp.name, dp.version);
            if let Some(entry) = self.get_packages(&base_key) {
                pruned_packages
                    .entry(base_key)
